# Look for any mentions of demo, task, grid patterns
for i, line in enumerate(lines):
    data = json.loads(line)
    text_content = ''

    # Extract text from assistant messages
    if data['type'] == 'message':
        msg = data.get('message', {})
        if msg.get('role') == 'assistant':
            content_list = msg.get('content', [])
            for item in content_list:
                if 'text' in item:
                    text_content += item['text']
                elif 'toolCall' in item:
                    name = item.get('name', '')
                    if name == 'ipython' and 'code' in item.get('arguments', {}):
                        text_content += item['arguments']['code']

        # For user messages
        if msg.get('role') == 'user':
            content_list = msg.get('content', [])
            for item in content_list:
                if 'text' in item:
                    text_content = item['text']

    # Check for key phrases
    if 'Demo pair' in text_content or 'Test input' in text_content:
        print(f"\nLine {i}: {json.dumps(data)[:300]}")

